```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities>
  a owl:Ontology ;
  rdfs:label "Securities and Financial Instruments Ontology" ;
  rdfs:comment "An ontology of securities, financial instruments, derivatives, issuers and markets, modelled from an encyclopedic/regulatory corpus on finance." .

#################################################################
# 1. CORE GENERIC CLASSES
#################################################################

fis:Asset a owl:Class ;
  rdfs:label "asset" ;
  rdfs:comment "Anything that can serve as collateral or as the underlying reference of a derivative or convertible instrument." .

fis:FinancialInstrument a owl:Class ;
  rdfs:subClassOf fis:Asset ;
  rdfs:label "financial instrument" ;
  rdfs:comment "A monetary contract between parties that can be created, traded, modified and settled (IAS 32: gives rise to a financial asset of one entity and a financial liability or equity instrument of another)." .

fis:CashInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "cash instrument" ;
  rdfs:comment "A financial instrument whose value is determined directly by the markets, e.g. securities, loans and deposits." .

fis:Derivative a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "derivative" ;
  rdfs:comment "A contract whose value derives from the value and characteristics of one or more underlying entities (asset, index, interest rate). Has four elements: an underlier, a future act, a price, and a future date (per corpus). NOTE: the US SEC passage lists derivatives as one of three broad categories of 'securities', conflicting with the cash-instrument/derivative-instrument split used elsewhere in the corpus; this ontology follows the majority cash-vs-derivative split and records derivatives as financial instruments distinct from, but comparable to, securities." .

fis:Security a owl:Class ;
  rdfs:subClassOf fis:CashInstrument ;
  rdfs:label "security" , "tradable financial asset" ;
  rdfs:comment "A tradable financial asset. Legal definition varies by jurisdiction: the UK FCA definition is narrower (equities, debentures, warrants, government/public securities, units, pension-scheme rights, etc.) while the US definition is broad, covering debt, equity and derivative securities. This ontology follows the broad corpus-wide treatment of security as encompassing debt, equity and hybrid securities." .

fis:Loan a owl:Class ;
  rdfs:subClassOf fis:CashInstrument ;
  rdfs:label "loan" ;
  rdfs:comment "A cash instrument where borrower and lender must agree on a transfer; unlike securities, loans are not readily transferable." .

fis:Deposit a owl:Class ;
  rdfs:subClassOf fis:CashInstrument ;
  rdfs:label "deposit" .

fis:Commodity a owl:Class ; rdfs:subClassOf fis:Asset ; rdfs:label "commodity" .
fis:Currency a owl:Class ; rdfs:subClassOf fis:Asset ; rdfs:label "currency" .
fis:PriceIndex a owl:Class ; rdfs:subClassOf fis:Asset ; rdfs:label "price index" .
fis:RealEstateAsset a owl:Class ; rdfs:subClassOf fis:Asset ; rdfs:label "real estate asset" .
fis:InterestRateBenchmark a owl:Class ; rdfs:subClassOf fis:Asset ; rdfs:label "interest rate benchmark" ;
  rdfs:comment "E.g. LIBOR, Euribor, SOFR used as a reference rate for floating-rate instruments." .

fis:Mortgage a owl:Class ; rdfs:subClassOf fis:Asset ; rdfs:label "mortgage" .
fis:ResidentialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage ; rdfs:label "residential mortgage" .
fis:CommercialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage ; rdfs:label "commercial mortgage" .
fis:PrimeMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage ; rdfs:label "prime mortgage" .
fis:AltAMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage ; rdfs:label "Alt-A mortgage" .
fis:SubprimeMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage ; rdfs:label "subprime mortgage" .

fis:Receivable a owl:Class ; rdfs:subClassOf fis:Asset ; rdfs:label "receivable" .
fis:CreditCardReceivable a owl:Class ; rdfs:subClassOf fis:Receivable ; rdfs:label "credit card receivable" .
fis:AutoLoan a owl:Class ; rdfs:subClassOf fis:Receivable ; rdfs:label "auto loan" .
fis:StudentLoan a owl:Class ; rdfs:subClassOf fis:Receivable ; rdfs:label "student loan" .
fis:HomeEquityLoan a owl:Class ; rdfs:subClassOf fis:Receivable ; rdfs:label "home equity loan" .

[] a owl:AllDisjointClasses ; owl:members ( fis:ResidentialMortgage fis:CommercialMortgage ) .
[] a owl:AllDisjointClasses ; owl:members ( fis:PrimeMortgage fis:AltAMortgage fis:SubprimeMortgage ) .

#################################################################
# 2. MARKETS
#################################################################

fis:Market a owl:Class ; rdfs:label "market" .
fis:PrimaryMarket a owl:Class ; rdfs:subClassOf fis:Market ;
  rdfs:comment "Market in which newly issued securities are offered, publicly or privately, to investors." .
fis:SecondaryMarket a owl:Class ; rdfs:subClassOf fis:Market ;
  rdfs:comment "Market in which previously issued securities are traded among investors." .
fis:StockExchange a owl:Class ; rdfs:subClassOf fis:SecondaryMarket ;
  rdfs:comment "An organized and officially recognized market on which securities can be bought and sold." .
fis:OverTheCounterMarket a owl:Class ; rdfs:subClassOf fis:Market ;
  rdfs:comment "Market in which buyers and sellers deal directly with each other, by telephone or electronically, rather than through an exchange." .
fis:MoneyMarket a owl:Class ; rdfs:subClassOf fis:Market ;
  rdfs:comment "Market for short-term funds, generally for a period of a year or less." .
fis:BondMarket a owl:Class ; rdfs:subClassOf fis:Market ;
  rdfs:comment "Market for interest-bearing securities with a maturity of at least one year." .
fis:DerivativesExchange a owl:Class ; rdfs:subClassOf fis:Market ;
  rdfs:comment "A market where individuals trade standardized derivative contracts defined by the exchange." .

[] a owl:AllDisjointClasses ; owl:members ( fis:PrimaryMarket fis:SecondaryMarket ) .

#################################################################
# 3. MARKET PARTICIPANTS
#################################################################

fis:MarketParticipant a owl:Class ; rdfs:label "market participant" .

fis:Issuer a owl:Class ; rdfs:subClassOf fis:MarketParticipant ;
  rdfs:comment "The company or other entity issuing a security." .
fis:SovereignGovernment a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:Municipality a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:SupranationalOrganization a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:FinancialInstitution a owl:Class ; rdfs:subClassOf fis:Issuer .

[] a owl:AllDisjointClasses ;
   owl:members ( fis:SovereignGovernment fis:Municipality fis:Corporation fis:SupranationalOrganization ) .

fis:Investor a owl:Class ; rdfs:subClassOf fis:MarketParticipant .
fis:RetailInvestor a owl:Class ; rdfs:subClassOf fis:Investor ;
  rdfs:comment "Members of the public investing personally, other than by way of business." .
fis:InstitutionalInvestor a owl:Class ; rdfs:subClassOf fis:Investor .
fis:InvestmentBank a owl:Class ; rdfs:subClassOf fis:InstitutionalInvestor .
fis:InsuranceCompany a owl:Class ; rdfs:subClassOf fis:InstitutionalInvestor .
fis:PensionFund a owl:Class ; rdfs:subClassOf fis:InstitutionalInvestor .
fis:SovereignWealthFund a owl:Class ; rdfs:subClassOf fis:InstitutionalInvestor .
fis:CentralBank a owl:Class ; rdfs:subClassOf fis:InstitutionalInvestor .

[] a owl:AllDisjointClasses ; owl:members ( fis:RetailInvestor fis:InstitutionalInvestor ) .

fis:Intermediary a owl:Class ; rdfs:subClassOf fis:MarketParticipant .
fis:BrokerDealer a owl:Class ; rdfs:subClassOf fis:Intermediary .
fis:Underwriter a owl:Class ; rdfs:subClassOf fis:Intermediary ;
  rdfs:comment "Buys an entire bond/share issue from the issuer and resells it to investors, taking the risk of being unable to sell it on." .
fis:ClearingHouse a owl:Class ; rdfs:subClassOf fis:Intermediary .
fis:CentralSecuritiesDepository a owl:Class ; rdfs:subClassOf fis:Intermediary ;
  rdfs:comment "E.g. the Depository Trust Company (DTC), which holds global certificates on behalf of participants." .
fis:CreditRatingAgency a owl:Class ; rdfs:subClassOf fis:Intermediary .

#################################################################
# 4. OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:Issuer ;
  rdfs:label "has issuer" .

fis:isIssuerOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasIssuer ;
  rdfs:domain fis:Issuer ; rdfs:range fis:Security .

fis:hasHolder a owl:ObjectProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:Investor ;
  rdfs:comment "The holder of a security is entitled to the rights under it (e.g. interest if debt, voting if equity)." .

fis:isHolderOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasHolder ;
  rdfs:domain fis:Investor ; rdfs:range fis:Security .

fis:hasUnderlying a owl:ObjectProperty , owl:FunctionalProperty ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range fis:Asset ;
  rdfs:label "has underlying" ;
  rdfs:comment "The underlier: the item that can or must be bought or sold under a derivative, or into which a convertible/warrant may be exchanged." .

fis:isUnderlyingOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasUnderlying ;
  rdfs:domain fis:Asset ; rdfs:range fis:FinancialInstrument .

fis:hasCollateral a owl:ObjectProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range fis:Asset ;
  rdfs:comment "The pool of assets whose cash flows back the payments of the debt security." .

fis:isCollateralOf a owl:ObjectProperty ;
  owl:inverseOf fis:hasCollateral ;
  rdfs:domain fis:Asset ; rdfs:range fis:DebtSecurity .

fis:hasReferenceEntity a owl:ObjectProperty ;
  rdfs:domain fis:CreditDefaultSwap ; rdfs:range fis:DebtSecurity ;
  rdfs:comment "The bond or loan on which a credit default swap is based." .

fis:hasListingVenue a owl:ObjectProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:Market .

#################################################################
# 5. DATATYPE PROPERTIES
#################################################################

fis:hasMaturityDate a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:date ;
  rdfs:comment "The date on which the issuer is obligated to repay the nominal amount; absent for perpetual bonds." .

fis:hasExpirationDate a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:date .

fis:hasDeliveryDate a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Derivative ; rdfs:range xsd:date ;
  rdfs:comment "The specified future date on which a forward or futures act of purchase/sale must take place." .

fis:hasFaceValue a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:decimal ;
  rdfs:label "has face value" ;
  rdfs:comment "Nominal, principal, par, or face amount: the amount on which the issuer pays interest and which is repaid at maturity." .

fis:hasCouponRate a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:decimal ;
  rdfs:comment "The interest rate the issuer pays to the holder, expressed per annum." .

fis:hasStrikePrice a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:decimal .

fis:hasYieldToMaturity a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:decimal .

fis:hasDividendRate a owl:DatatypeProperty ;
  rdfs:domain fis:Stock ; rdfs:range xsd:decimal .

fis:hasNotionalAmount a owl:DatatypeProperty ;
  rdfs:domain fis:Derivative ; rdfs:range xsd:decimal ;
  rdfs:comment "The nominal amount used to calculate payments under a swap or other derivative; usually not exchanged." .

fis:hasConversionRatio a owl:DatatypeProperty ;
  rdfs:domain fis:ConvertibleBond ; rdfs:range xsd:decimal .

fis:hasCreditRating a owl:DatatypeProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:string .

fis:hasMarketCapitalization a owl:DatatypeProperty ;
  rdfs:domain fis:Stock ; rdfs:range xsd:decimal .

fis:hasCurrencyOfDenomination a owl:DatatypeProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:string .

fis:hasPremium a owl:DatatypeProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:decimal .

fis:hasCumulativeDividend a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:PreferredStock ; rdfs:range xsd:boolean .

fis:hasCallFeature a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:boolean .

fis:hasPutFeature a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:boolean .

fis:hasTradingVenueType a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Derivative ; rdfs:range xsd:string ;
  rdfs:comment "Value 'exchange' or 'OTC'." .

fis:hasBalanceSheetTreatment a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:string ;
  rdfs:comment "Value 'onBalanceSheet' (e.g. covered bonds) or 'offBalanceSheet' (e.g. asset-backed securities)." .

fis:hasCashFlowComponent a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:StrippedMortgageBackedSecurity ; rdfs:range xsd:string ;
  rdfs:comment "Value 'interest' or 'principal'." .

fis:hasOptionType a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:string ;
  rdfs:comment "Value 'call' or 'put'." .

fis:hasExerciseStyle a owl:DatatypeProperty , owl:FunctionalProperty ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range xsd:string ;
  rdfs:comment "Value 'American', 'European', or 'Bermudan'; used for options and for callable bonds' call-date structure." .

#################################################################
# 6. DEBT SECURITY / EQUITY SECURITY / HYBRID SECURITY TOP SPLIT
#################################################################

fis:DebtSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "debt security" ;
  rdfs:comment "Holder is entitled to payment of principal and interest; generally issued for a fixed term and redeemable at the end of that term." .

fis:EquitySecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "equity security" ;
  rdfs:comment "A share of equity interest in an entity; not entitled to any fixed payment, shares only the residual interest after creditors are paid, but enjoys pro rata control and upside." .

fis:HybridSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "hybrid security" ;
  rdfs:comment "Combines characteristics of both debt and equity securities, e.g. preference shares, convertibles, equity warrants. NOTE: this four-category taxonomy (debt, equity, derivative, hybrid) differs from the US SEC's three-way split (debt, equity, derivatives) which has no separate hybrid category; the corpus narrative on hybrid securities is treated here as authoritative for classifying preferred stock, convertibles and warrants." .

[] a owl:AllDisjointClasses ; owl:members ( fis:DebtSecurity fis:EquitySecurity ) .

fis:SecuredDebtSecurity a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "Protected by collateral." .
fis:UnsecuredDebtSecurity a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "Not protected by collateral; also called a debenture." .
[] a owl:AllDisjointClasses ; owl:members ( fis:SecuredDebtSecurity fis:UnsecuredDebtSecurity ) .

fis:SeniorDebtSecurity a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "Contractually senior; holders have priority in bankruptcy." .
fis:SubordinatedDebtSecurity a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "Debt that is not senior." .
[] a owl:AllDisjointClasses ; owl:members ( fis:SeniorDebtSecurity fis:SubordinatedDebtSecurity ) .

fis:Debenture a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:UnsecuredDebtSecurity ) ] ;
  rdfs:label "debenture" ;
  rdfs:comment "Unsecured bond; typically long maturity of at least ten years." .

#################################################################
# 7. BOND HIERARCHY
#################################################################

fis:Bond a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:label "bond" ;
  rdfs:comment "Issuer owes holder a debt and is obliged to pay the principal at maturity plus interest (coupon)." .

### By issuer
fis:GovernmentBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] ;
  rdfs:label "government bond" , "sovereign bond" , "treasury bond" .

fis:MunicipalBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Municipality ] ) ] ;
  rdfs:label "municipal bond" , "muni" .

fis:CorporateBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] ;
  rdfs:label "corporate bond" .

fis:SupranationalBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ] ) ] ;
  rdfs:label "supranational bond" , "supra" .

[] a owl:AllDisjointClasses ;
   owl:members ( fis:GovernmentBond fis:MunicipalBond fis:CorporateBond fis:SupranationalBond ) .
# NOTE: corpus states the term "corporate bond" sometimes also encompasses bonds of supranational
# organisations; the disjointness above follows the stricter, more common usage.

fis:WarBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "Issued by a government to fund military operations and wartime expenditure." .
fis:ClimateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Issued by a government or corporate entity to raise finance for climate mitigation/adaptation." .
fis:SocialImpactBond a owl:Class ; rdfs:subClassOf fis:Bond .

fis:GeneralObligationBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Principal and interest secured by the full faith and credit of the issuer's taxing power." .
fis:AssessmentBond a owl:Class ; rdfs:subClassOf fis:GeneralObligationBond ;
  rdfs:comment "Repayment based on property tax assessments; still a general obligation if assessments fail." .
fis:RevenueBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Guarantee of repayment solely from revenues of a specified revenue-generating project; typically non-recourse." .

fis:Gilt a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "UK government bond." .
fis:ConventionalGilt a owl:Class ; rdfs:subClassOf fis:Gilt .
fis:IndexLinkedGilt a owl:Class ; rdfs:subClassOf fis:Gilt .

fis:TreasuryNote a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "US Treasury security with maturity of two to ten years." .
fis:TreasuryBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond ;
  rdfs:comment "US Treasury security with the longest maturity, 20 to 30 years." .
fis:TreasuryInflationProtectedSecurity a owl:Class ;
  rdfs:subClassOf fis:GovernmentBond , fis:InflationIndexedBond ;
  rdfs:label "TIPS" .

### Euro debt securities
fis:EuroDebtSecurity a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "Issued internationally outside the domestic market of the issuer, in a denomination different from the issuer's domicile." .
fis:Eurobond a owl:Class ; rdfs:subClassOf fis:Bond , fis:EuroDebtSecurity ;
  rdfs:comment "Characteristically underwritten, unsecured, interest paid gross." .
fis:Euronote a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument , fis:EuroDebtSecurity .

### By coupon / payment structure
fis:FixedRateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Coupon remains constant throughout the life of the bond." .
fis:FloatingRateNote a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "floating rate note" , "FRN" ;
  rdfs:comment "Coupon is recalculated periodically based on a reference rate such as LIBOR/SOFR/Euribor." .
fis:ZeroCouponBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Pays no regular interest; issued at a substantial discount to par, full principal repaid at maturity." .
fis:InflationIndexedBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Principal and interest indexed to a consumer price level." .
fis:LotteryBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Issuer redeems randomly selected bonds within the issue on a schedule, some at higher than face value." .

[] a owl:AllDisjointClasses ; owl:members ( fis:FixedRateBond fis:FloatingRateNote fis:ZeroCouponBond ) .

### By maturity feature
fis:PerpetualBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasMaturityDate ; owl:onDataRange xsd:date ;
        owl:qualifiedCardinality "0"^^xsd:nonNegativeInteger ] ) ] ;
  rdfs:label "perpetual bond" , "perpetuity" , "irredeemable bond" ;
  rdfs:comment "A bond with no maturity date." .

fis:SerialBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Matures in installments over a period of time." .
fis:MethuselahBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Maturity of 50 years or longer." .

### By embedded option
fis:CallableBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCallFeature ; owl:hasValue true ] ) ] ;
  rdfs:comment "Issuer may repay the bond before maturity on call dates." .
fis:PutableBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasPutFeature ; owl:hasValue true ] ) ] ;
  rdfs:label "putable bond" , "retractable bond" .
fis:BulletBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCallFeature ; owl:hasValue false ]
      [ a owl:Restriction ; owl:onProperty fis:hasPutFeature ; owl:hasValue false ] ) ] ;
  rdfs:comment "A straight bond that is neither callable nor putable." .

fis:BermudanCallableBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:CallableBond
      [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "Bermudan" ] ) ] .
fis:EuropeanCallableBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:CallableBond
      [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "European" ] ) ] .
fis:AmericanCallableBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:CallableBond
      [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:hasValue "American" ] ) ] .
fis:DeathPutBond a owl:Class ; rdfs:subClassOf fis:PutableBond ;
  rdfs:comment "Survivor's option: beneficiary of a deceased bondholder's estate may put the bond back at face value." .

### By certificate form (reusing cross-cutting Security dichotomies defined in section 9)
fis:BearerBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:BearerSecurity ) ] .
fis:RegisteredBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:RegisteredSecurity ) ] .
fis:BookEntryBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond fis:NonCertificatedSecurity ) ] .

### By credit quality
fis:InvestmentGradeBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Rated AAA, AA, A or BBB." .
fis:HighYieldBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:label "junk bond" ;
  rdfs:comment "Rated below investment grade (BB and below)." .
[] a owl:AllDisjointClasses ; owl:members ( fis:InvestmentGradeBond fis:HighYieldBond ) .

### Asset-backed family
fis:AssetBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Asset ]
      [ a owl:Restriction ; owl:onProperty fis:hasBalanceSheetTreatment ; owl:hasValue "offBalanceSheet" ] ) ] ;
  rdfs:label "asset-backed security" , "ABS" ;
  rdfs:comment "Bond whose interest and principal are backed by cash flows from a pool of assets; the assets are removed from the issuer's balance sheet (contrast with covered bonds)." .

fis:CoveredBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Asset ]
      [ a owl:Restriction ; owl:onProperty fis:hasBalanceSheetTreatment ; owl:hasValue "onBalanceSheet" ] ) ] ;
  rdfs:comment "Backed by cash flows from mortgages or public-sector assets which remain on the issuer's balance sheet, unlike asset-backed securities." .

fis:MortgageBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Mortgage ] ) ] ;
  rdfs:label "mortgage-backed security" , "MBS" .

fis:ResidentialMortgageBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MortgageBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:ResidentialMortgage ] ) ] ;
  rdfs:label "RMBS" .

fis:CommercialMortgageBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MortgageBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:CommercialMortgage ] ) ] ;
  rdfs:label "CMBS" .

fis:CollateralizedMortgageObligation a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:label "CMO" , "pay-through bond" ;
  rdfs:comment "Divided into tranches with different maturities and payment priorities." .

fis:StrippedMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:label "SMBS" .
fis:InterestOnlyStrip a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:StrippedMortgageBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCashFlowComponent ; owl:hasValue "interest" ] ) ] ;
  rdfs:label "IO strip" .
fis:PrincipalOnlyStrip a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:StrippedMortgageBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCashFlowComponent ; owl:hasValue "principal" ] ) ] ;
  rdfs:label "PO strip" .
fis:NetInterestMarginSecurity a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity ;
  rdfs:label "NIMS" ; rdfs:comment "Re-securitized residual interest of a mortgage-backed security." .

fis:CollateralizedDebtObligation a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:DebtSecurity ] ) ] ;
  rdfs:label "CDO" .

fis:HomeEquityLoanBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:HomeEquityLoan ] ) ] .
fis:AutoLoanBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:AutoLoan ] ) ] .
fis:CreditCardBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:CreditCardReceivable ] ) ] .
fis:StudentLoanBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:AssetBackedSecurity
      [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:StudentLoan ] ) ] ;
  rdfs:label "SLABS" .

### Convertible / exchangeable bonds (hybrid)
fis:ConvertibleBond a owl:Class ;
  rdfs:subClassOf fis:HybridSecurity ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:Bond
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:CommonStock ] ) ] ;
  rdfs:label "convertible bond" , "convertible note" , "convertible debenture" ;
  rdfs:comment "A bond the holder can convert into a specified number of shares of the issuer's common stock." .

fis:MandatoryConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "Forces the holder to convert into shares at maturity." .
fis:ContingentConvertibleBond a owl:Class ; rdfs:subClassOf fis:MandatoryConvertibleBond ;
  rdfs:label "CoCo" ;
  rdfs:comment "Automatically converted into equity if a pre-specified trigger event occurs." .
fis:PackagedConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "A straight bond and a call option/warrant wrapped together, tradeable as separate legs." .
fis:SyntheticConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "Issued by an investment bank to replicate a convertible payoff on a specific underlying equity, cash-settled." .
fis:ExchangeableBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "Allows exchange into shares of a corporation other than the issuer." .
fis:ConvertibleNote a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "Frequent vehicle for seed investing in startups; debt that converts to equity in a future round." .

#################################################################
# 8. MONEY MARKET INSTRUMENTS
#################################################################

fis:MoneyMarketInstrument a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "Short-term debt instrument with original maturity of one year or less; highly liquid, sometimes called 'near cash'." .

fis:CommercialPaper a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "Unsecured promissory note with fixed maturity usually less than 270 days." .
fis:EuroCommercialPaper a owl:Class ; rdfs:subClassOf fis:CommercialPaper , fis:Euronote ;
  rdfs:label "ECP" .

fis:CertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument , fis:Deposit ;
  rdfs:label "CD" , "time deposit" .
fis:EuroCertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:CertificateOfDeposit , fis:Euronote .
fis:JumboCertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:CertificateOfDeposit ;
  rdfs:comment "Minimum deposit of $100,000; negotiable, in bearer form." .

fis:TreasuryBill a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:MoneyMarketInstrument
