  rdfs:comment "Short-term debt obligation of a national government, maturing in three to twelve months; zero-coupon, bought at a discount." .

fis:BankersAcceptance a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument .
fis:RepurchaseAgreement a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "Short-term loan arranged by selling securities with an agreement to repurchase at a fixed price on a fixed date." .
fis:MunicipalNote a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument , fis:Municipality .

#################################################################
# 9. SECURITY FORM / TRANSFERABILITY DICHOTOMIES
#################################################################

fis:CertificatedSecurity a owl:Class ; rdfs:subClassOf fis:Security .
