[] a owl:AllDisjointClasses ; owl:members ( fis:DividedSecurity fis:UndividedSecurity ) .

fis:FungibleSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "All holdings are treated identically and are interchangeable." .
fis:NonFungibleSecurity a owl:Class ; rdfs:subClassOf fis:Security .
[] a owl:AllDisjointClasses ; owl:members ( fis:FungibleSecurity fis:NonFungibleSecurity ) .

fis:RestrictedSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Acquired in unregistered form, e.g. from the issuing company (SEC Rule 144)." .
fis:ControlSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Acquired from an affiliate of the issuer (SEC Rule 144)." .

#################################################################
# 10. EQUITY SECURITIES / STOCK
#################################################################

fis:Stock a owl:Class ; rdfs:subClassOf fis:EquitySecurity ;
  rdfs:label "stock" , "share" , "capital stock" ;
  rdfs:comment "Fractional ownership of a corporation." .

fis:CommonStock a owl:Class ; rdfs:subClassOf fis:Stock ;
  rdfs:label "common stock" , "ordinary share" , "equity share" ;
  rdfs:comment "Typically carries voting rights; lowest priority on dividends and liquidation proceeds." .

fis:PreferredStock a owl:Class ;
  rdfs:subClassOf fis:Stock , fis:HybridSecurity ;
  rdfs:label "preferred stock" , "preference share" ;
  rdfs:comment "Component of share capital combining equity and debt features; senior to common stock but subordinate to bonds; generally has priority on dividends and liquidation but usually no voting rights. NOTE: under IAS 32, a mandatorily redeemable preference share is instead classified as a financial liability rather than equity, which conflicts with the common market classification of preferred stock as equity; this ontology follows the market taxonomy and records the IAS 32 divergence here." .

[] a owl:AllDisjointClasses ; owl:members ( fis:CommonStock fis:PreferredStock ) .

fis:CumulativePreferredStock a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
      [ a owl:Restriction ; owl:onProperty fis:hasCumulativeDividend ; owl:hasValue true ] ) ] ;
  rdfs:comment "Unpaid dividends accumulate as dividends in arrears." .
fis:NoncumulativePreferredStock a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
      [ a owl:Restriction ; owl:onProperty fis:hasCumulativeDividend ; owl:hasValue false ] ) ] ;
  rdfs:label "straight preferred stock" .

fis:ConvertiblePreferredStock a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( fis:PreferredStock
      [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:CommonStock ] ) ] ;
  rdfs:comment "Includes the ability to convert the preferred shares into a fixed number of common shares." .

fis:PerpetualPreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock .
fis:CallablePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  rdfs:comment "Carries a call provision enabling the issuer to repurchase the share at its discretion." .

#################################################################
# 11. DEPOSITARY RECEIPTS
#################################################################

fis:DepositaryReceipt a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:label "depositary receipt" , "DR" ;
  rdfs:comment "A negotiable financial instrument issued by a bank to represent a foreign company's publicly traded securities, trading on a local stock exchange." .

fis:AmericanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
  rdfs:label "ADR" ; rdfs:comment "Listed and traded in the United States." .
fis:GlobalDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
  rdfs:label "GDR" .
fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt ;
  rdfs:label "EDR" .

[] a owl:AllDisjointClasses ;
