fis:StockFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ; rdfs:label "equity fund" .
fis:BondFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ; rdfs:label "income fund" .
fis:BalancedFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
